#include "diamond.h"

#include <algorithm>
#include <string>

namespace diamond {

std::string print(char letter) {
    const int last = letter - 'A';
    const int width = 2 * last + 1;
    std::string result;

    for (int row = 0; row <= 2 * last; ++row) {
        const int level = std::min(row, 2 * last - row);
        const int padding = last - level;

        result.append(padding, ' ');
        result.push_back(static_cast<char>('A' + level));

        if (level > 0) {
            result.append(2 * level - 1, ' ');
            result.push_back(static_cast<char>('A' + level));
        }

        result.append(width - padding -
                         (level == 0 ? 1 : 2 * level + 1),
                     ' ');
        result.push_back('\n');
    }

    return result;
}

}  // namespace diamond
```

